#if canImport(AppKit)
import AppKit

extension ControlRoomLook {
    /// The theme for what a view is being drawn in right now.
    static func theme(for appearance: NSAppearance) -> Theme {
        theme(dark: appearance.bestMatch(from: [.darkAqua, .aqua]) == .darkAqua)
    }
}
#endif
